package com.studenttracker.service;
import com.studenttracker.database.DatabaseManager; import com.studenttracker.model.StudySession; import java.sql.*; import java.time.*; import java.util.*;
public class StudySessionService {private final DatabaseManager db; public StudySessionService(DatabaseManager db){this.db=db;} public int add(StudySession s)throws SQLException{String q="INSERT INTO study_sessions(subject,start_time,end_time,minutes) VALUES(?,?,?,?)";try(PreparedStatement p=db.getConnection().prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,s.getSubject());p.setString(2,s.getStartTime().toString());p.setString(3,s.getEndTime().toString());p.setInt(4,s.getMinutes());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);}}return 0;} public List<StudySession> all()throws SQLException{List<StudySession> x=new ArrayList<>();try(Statement s=db.getConnection().createStatement();ResultSet r=s.executeQuery("SELECT * FROM study_sessions ORDER BY start_time DESC")){while(r.next())x.add(new StudySession(r.getInt("id"),r.getString("subject"),LocalDateTime.parse(r.getString("start_time")),LocalDateTime.parse(r.getString("end_time")),r.getInt("minutes")));}return x;} public int totalMinutes(){try(Statement s=db.getConnection().createStatement();ResultSet r=s.executeQuery("SELECT COALESCE(SUM(minutes),0) FROM study_sessions")){return r.next()?r.getInt(1):0;}catch(SQLException e){return 0;}} }
